<div class="page-heading"><h1>Notifikasi</h1><p>Informasi pendaftaran, materi, jadwal, dan hasil belajar Anda.</p></div>
<?php $page=max(1,(int)query('page','1'));$offset=($page-1)*30;$notifications=rows('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT 31 OFFSET '.$offset,[$uid]);$hasMore=count($notifications)>30;$notifications=array_slice($notifications,0,30); ?>
<?php if($notifications): ?><form method="post" style="margin-bottom:20px" data-busy-form><?= actionFields('read_notifications') ?><button type="submit" class="btn secondary">Tandai semua sudah dibaca</button></form><div class="stack"><?php foreach($notifications as $notification): ?><article class="panel"><div class="row"><h2><?= e($notification['title']) ?></h2><?php if(!$notification['read_at']): ?><span class="badge">Baru</span><?php endif; ?></div><p class="muted"><?= e($notification['created_at']) ?></p><p style="margin-top:12px"><?= e($notification['body']) ?></p><div class="actions"><a class="btn secondary" href="portal.php?view=<?= e(isset($navigation[$notification['destination']])?$notification['destination']:'overview') ?>">Lihat informasi</a></div></article><?php endforeach; ?></div><div class="actions"><?php if($page>1): ?><a class="btn secondary" href="portal.php?view=notifications&amp;page=<?= $page-1 ?>">Sebelumnya</a><?php endif; ?><?php if($hasMore): ?><a class="btn secondary" href="portal.php?view=notifications&amp;page=<?= $page+1 ?>">Berikutnya</a><?php endif; ?></div><?php else: emptyState('Belum ada notifikasi','Pemberitahuan terbaru akan muncul di sini.','portal.php','Kembali ke ringkasan');endif; ?>
